-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.media_original_name_is_valid(p_name text, p_mime text)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.media_original_name_is_valid(p_name text, p_mime text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT p_name IS NOT NULL AND p_name = btrim(p_name)
     AND char_length(p_name) BETWEEN 1 AND 255
     AND p_name !~ '[[:cntrl:]/\\]'
     AND p_name NOT IN ('.', '..')
     AND CASE p_mime
       WHEN 'image/jpeg' THEN lower(p_name) ~ '\.(jpg|jpeg)$'
       WHEN 'image/png'  THEN lower(p_name) ~ '\.png$'
       WHEN 'image/webp' THEN lower(p_name) ~ '\.webp$'
       ELSE false
     END
$function$
